import {Label} from "@/components/ui/label";
import {Select,SelectContent,SelectItem,SelectTrigger,SelectValue} from "@/components/ui/select";
import {Dialog,DialogContent,DialogDescription,DialogHeader,DialogTitle} from "@/components/ui/dialog";
import {useReferenceOptions} from "@/hooks/use-reference-options";

type Section="setup"|"puc"|"centers"|"periods"|"opening"|"documents"|"balance"|"reports"|"compliance";
type OpeningMode="ZeroDeclared"|"ImportedAndApproved";
type OpeningDraftLine={accountId:string;partyId:string|null;costCenterId:string|null;description:string;debit:string;credit:string};
const money=new Intl.NumberFormat("es-CO",{style:"currency",currency:"COP",maximumFractionDigits:0});
const year=new Date().getFullYear(),yearStart=`${year}-01-01`,yearEnd=`${year}-12-31`;

function Input(props:ComponentProps<typeof BaseInput>){
  if(props.type!=="date")return <BaseInput {...props}/>;
  const {value,onChange,disabled,className}=props;
  return <DatePicker value={String(value??"")} disabled={disabled} className={className}
    onChange={next=>onChange?.({target:{value:next},currentTarget:{value:next}} as never)}/>;
}

export default function AccountingConfigurationPage(){
  const tenantId=useTenantContextStore(state=>state.selectedTenantId),businessId=useBusinessContextStore(state=>state.selectedBusinessId),queryClient=useQueryClient();
  const key=["accounting",tenantId,businessId],enabled=Boolean(tenantId&&businessId);
  const [section,setSection]=useState<Section>("setup"),[scope,setScope]=useState<"tenant"|"business">("tenant"),[from,setFrom]=useState(yearStart),[to,setTo]=useState(yearEnd),[effectiveFrom,setEffectiveFrom]=useState(yearStart),[openingMode,setOpeningMode]=useState<OpeningMode>("ZeroDeclared");
  const openingModes=useReferenceOptions("accounting-opening-balance-mode",enabled);
  const accounts=useQuery({queryKey:[...key,"accounts"],queryFn:accountingApi.accounts,enabled});
  const centers=useQuery({queryKey:[...key,"centers"],queryFn:accountingApi.costCenters,enabled});
  const periods=useQuery({queryKey:[...key,"periods"],queryFn:accountingApi.periods,enabled});
  const mappings=useQuery({queryKey:[...key,"mappings"],queryFn:accountingApi.mappings,enabled});
  const definitions=useQuery({queryKey:[...key,"category-definitions"],queryFn:accountingApi.categoryDefinitions,enabled});
  const readiness=useQuery({queryKey:[...key,"readiness",effectiveFrom,openingMode],queryFn:()=>accountingApi.readiness(effectiveFrom,openingMode),enabled});
  const balance=useQuery({queryKey:[...key,"trial-balance",from,to],queryFn:()=>accountingApi.trialBalance(from,to),enabled:enabled&&section==="balance"});
  const payables=useQuery({queryKey:[...key,"manual-payables"],queryFn:()=>payablesApi.list({page:1,pageSize:100}),enabled:enabled&&section==="documents"});
  const receivables=useQuery({queryKey:[...key,"manual-receivables"],queryFn:()=>receivablesApi.list({page:1,pageSize:100}),enabled:enabled&&section==="documents"});
  const refresh=async()=>queryClient.invalidateQueries({queryKey:key});
  const defaults=useMutation({mutationFn:accountingApi.ensureDefaults,onSuccess:async result=>{await refresh();toast.success(result.isReady?"Contabilidad Auraly configurada":"Configuración aplicada; revisa los pendientes")},onError:showError});
  const activate=useMutation({mutationFn:()=>accountingApi.activate({effectiveFrom,functionalCurrencyCode:"COP",openingBalanceMode:openingMode}),onSuccess:async result=>{await refresh();toast.success(result.status==="Ready"?(openingMode==="ZeroDeclared"?"Motor contable activado desde cero":"Motor contable activado con su asiento de apertura"):"El asiento de apertura quedó en procesamiento; las ventas contables se habilitan al finalizar")},onError:showError});
  const mapping=useMutation({mutationFn:({category,accountId}:{category:string;accountId:string})=>accountingApi.setMapping({tenantId:tenantId!,businessId:scope==="business"?businessId:null,category,accountId,effectiveFrom:"2000-01-01",effectiveTo:null}),onSuccess:async()=>{await refresh();toast.success("Cuenta automática actualizada")},onError:showError});
  const accountRows=accounts.data??[],postingAccounts=accountRows.filter(item=>item.isActive&&item.allowsPosting);
  const activeMappings=useMemo(()=>{const result=new Map<string,string>();for(const item of [...(mappings.data??[])].sort((a,b)=>Number(Boolean(a.businessId))-Number(Boolean(b.businessId))))result.set(item.category,item.accountId);return result},[mappings.data]);
  const categoryRows=definitions.data??[],requiredCategories=categoryRows.filter(item=>item.isRequired),today=new Date().toISOString().slice(0,10),mappedCount=requiredCategories.filter(item=>activeMappings.has(item.category)).length,hasCenter=(centers.data??[]).some(item=>item.isActive&&item.isDefault),hasPeriod=(periods.data??[]).some(item=>item.status==="Open"&&item.startsOn<=today&&item.endsOn>=today);
  const configurationReady=categoryRows.length>0&&mappedCount===requiredCategories.length&&hasCenter&&hasPeriod;
  const accountingReady=readiness.data?.status==="Ready";
  if(!tenantId||!businessId)return <EmptyContext/>;
  return <div className="space-y-5">
    <header className="overflow-hidden rounded-3xl bg-gradient-to-r from-slate-950 via-cyan-950 to-teal-700 p-6 text-white shadow-lg"><div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-cyan-200">Motor contable Auraly</p><h1 className="mt-2 text-3xl font-black">Contabilidad clara y automática</h1><p className="mt-2 max-w-2xl text-sm text-cyan-50/80">Configura una vez el PUC y revisa cómo ventas, compras, inventario, devoluciones y caja acumulan sus movimientos.</p></div><Button className="h-12 bg-white text-slate-950 hover:bg-cyan-50" disabled={defaults.isPending||accountingReady} onClick={()=>defaults.mutate()}>{defaults.isPending?<Loader2 className="mr-2 h-4 w-4 animate-spin"/>:<Settings2 className="mr-2 h-4 w-4"/>}{configurationReady?"Verificar configuración":"Configurar Auraly"}</Button></div></header>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatusCard label="Motor contable" value={accountingReady?"Activo y contabilizando":readiness.data?.status==="Configuring"?"En configuración":"Desactivado"} ok={accountingReady}/><StatusCard label="PUC activo" value={`${accountRows.filter(x=>x.isActive).length} cuentas`} ok={accountRows.length>=requiredCategories.length}/><StatusCard label="Cuentas automáticas" value={`${mappedCount}/${requiredCategories.length} conceptos`} ok={requiredCategories.length>0&&mappedCount===requiredCategories.length}/><StatusCard label="Periodo actual" value={hasPeriod?"Abierto":"Sin periodo abierto"} ok={hasPeriod}/></div>
    {!accountingReady&&<Card className="rounded-3xl border-amber-300 bg-amber-50/40"><CardHeader><CardTitle>Activación controlada</CardTitle><p className="text-sm text-muted-foreground">Auraly valida la configuración antes de activar. Los documentos anteriores a la fecha efectiva no se contabilizan automáticamente.</p></CardHeader><CardContent className="grid gap-4 lg:grid-cols-[14rem_minmax(18rem,1fr)_auto] lg:items-start"><Field label="Fecha efectiva"><Input type="date" value={effectiveFrom} onChange={event=>setEffectiveFrom(event.target.value)}/></Field><Field label="Cómo iniciar"><Select value={openingMode} onValueChange={value=>setOpeningMode(value as OpeningMode)} disabled={openingModes.isLoading}><SelectTrigger><SelectValue placeholder="Seleccionar inicio contable"/></SelectTrigger><SelectContent>{(openingModes.data??[]).map(option=><SelectItem key={option.code} value={option.code}>{option.label}</SelectItem>)}</SelectContent></Select><small className="text-muted-foreground">{openingModes.data?.find(option=>option.code===openingMode)?.description}</small></Field><Button className="lg:mt-6" disabled={!readiness.data||readiness.isFetching||readiness.data.blockingIssues.length>0||activate.isPending||openingModes.isLoading} onClick={()=>activate.mutate()}>{(activate.isPending||readiness.isFetching)&&<Loader2 className="mr-2 h-4 w-4 animate-spin"/>}Activar contabilidad</Button>{Boolean(readiness.data?.blockingIssues.length)&&<div className="lg:col-span-3 rounded-xl border border-amber-300 bg-amber-100/60 p-3 text-sm"><strong>Falta resolver:</strong><ul className="mt-2 list-disc pl-5">{readiness.data?.blockingIssues.map(issue=><li key={issue}>{issue}</li>)}</ul>{openingMode==="ImportedAndApproved"&&<Button type="button" variant="link" className="mt-1 h-auto p-0" onClick={()=>setSection("opening")}>Ir a Saldos iniciales</Button>}</div>}{readiness.data&&readiness.data.blockingIssues.length===0&&<div className="lg:col-span-3 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900"><strong>Configuración validada.</strong> {openingMode==="ImportedAndApproved"?"Los saldos aprobados se convertirán en el asiento de apertura.":"La contabilidad iniciará en cero."}</div>}</CardContent></Card>}
    <nav className="flex gap-1 overflow-x-auto rounded-2xl border bg-card p-1"><Nav active={section==="setup"} icon={Settings2} onClick={()=>setSection("setup")}>Automatización</Nav><Nav active={section==="puc"} icon={BookOpen} onClick={()=>setSection("puc")}>Plan de cuentas</Nav><Nav active={section==="centers"} icon={Building2} onClick={()=>setSection("centers")}>Centros de costo</Nav><Nav active={section==="periods"} icon={CalendarRange} onClick={()=>setSection("periods")}>Periodos</Nav><Nav active={section==="opening"} icon={Landmark} onClick={()=>setSection("opening")}>Saldos iniciales</Nav><Nav active={section==="documents"} icon={FilePenLine} onClick={()=>setSection("documents")}>Documentos manuales</Nav><Nav active={section==="balance"} icon={TableProperties} onClick={()=>setSection("balance")}>Balance de comprobación</Nav><Nav active={section==="reports"} icon={BarChart3} onClick={()=>setSection("reports")}>Libros y estados</Nav><Nav active={section==="compliance"} icon={TableProperties} onClick={()=>setSection("compliance")}>Fiscal y exógena</Nav></nav>
    {section==="setup"&&(
      <AutomationSection categories={categoryRows} accounts={postingAccounts} mapped={activeMappings} mappedCount={mappedCount} scope={scope} setScope={setScope} pending={mapping.isPending} onMap={(category,accountId)=>mapping.mutate({category,accountId})}/>
    )}
    {section==="puc"&&(
      <AccountsSection tenantId={tenantId} rows={accountRows} refresh={refresh}/>
    )}
    {section==="centers"&&(
      <CentersSection businessId={businessId} rows={centers.data??[]} refresh={refresh}/>
    )}
    {section==="periods"&&(
      <PeriodsSection tenantId={tenantId} rows={periods.data??[]} refresh={refresh}/>
    )}
    {section==="opening"&&(
      <OpeningBalancesSection businessId={businessId} effectiveOn={effectiveFrom} setEffectiveOn={setEffectiveFrom} accounts={postingAccounts} centers={(centers.data??[]).filter(item=>item.isActive)} accountingReady={accountingReady} refresh={refresh}/>
    )}
    {section==="documents"&&(
      <ManualDocumentsSection businessId={businessId} accounts={postingAccounts} centers={centers.data??[]} payables={payables.data?.items??[]} receivables={receivables.data?.items??[]} refresh={refresh}/>
    )}
    {section==="balance"&&(
      <BalanceSection contextKey={`${tenantId}:${businessId}`} from={from} to={to} setFrom={setFrom} setTo={setTo} rows={balance.data??[]} loading={balance.isFetching} refresh={()=>void balance.refetch()}/>
    )}
    {section==="reports"&&(
      <ReportsSection contextKey={`${tenantId}:${businessId}`} from={from} to={to} setFrom={setFrom} setTo={setTo}/>
    )}
    {section==="compliance"&&(
      <ComplianceSection contextKey={`${tenantId}:${businessId}`} businessId={businessId} accounts={postingAccounts}/>
    )}
  </div>
}

function OpeningBalancesSection({businessId,effectiveOn,setEffectiveOn,accounts,centers,accountingReady,refresh}:{businessId:string;effectiveOn:string;setEffectiveOn:(value:string)=>void;accounts:Array<{accountId:string;code:string;name:string;requiresParty:boolean}>;centers:Array<{costCenterId:string;code:string;name:string;isDefault:boolean}>;accountingReady:boolean;refresh:()=>Promise<unknown>}){
  const client=useQueryClient();
  const queryKey=["accounting-opening-balance",businessId,effectiveOn];
  const opening=useQuery({queryKey,queryFn:()=>accountingApi.openingBalance(effectiveOn),enabled:Boolean(businessId&&effectiveOn)});
  const emptyLine=():OpeningDraftLine=>({accountId:"",partyId:null,costCenterId:centers.find(item=>item.isDefault)?.costCenterId??null,description:"Saldo inicial",debit:"",credit:""});
  const [batchId,setBatchId]=useState(crypto.randomUUID()),[rowVersion,setRowVersion]=useState<string|null>(null),[description,setDescription]=useState(`Saldos iniciales al ${effectiveOn}`),[lines,setLines]=useState<OpeningDraftLine[]>([emptyLine(),emptyLine()]);
  useEffect(()=>{
    if(opening.data===undefined)return;
    if(opening.data){setBatchId(opening.data.batchId);setRowVersion(opening.data.rowVersion);setDescription(opening.data.description);setLines(opening.data.lines.map(line=>({accountId:line.accountId,partyId:line.partyId,costCenterId:line.costCenterId,description:line.description,debit:line.debit?String(line.debit):"",credit:line.credit?String(line.credit):""})));return}
    setBatchId(crypto.randomUUID());setRowVersion(null);setDescription(`Saldos iniciales al ${effectiveOn}`);setLines([emptyLine(),emptyLine()]);
  // centers only supplies the initial default; changing the catalog must not overwrite an in-progress draft.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[opening.data,effectiveOn]);
  const status=opening.data?.status??"Draft",editable=!accountingReady&&status==="Draft";
  const update=(index:number,change:Partial<OpeningDraftLine>)=>setLines(current=>current.map((line,position)=>position===index?{...line,...change}:line));
  const normalized=lines.map(line=>({...line,debit:Number(line.debit||0),credit:Number(line.credit||0)}));
  const debit=normalized.reduce((total,line)=>total+line.debit,0),credit=normalized.reduce((total,line)=>total+line.credit,0),balanced=debit>0&&Math.abs(debit-credit)<0.0001;
  const valid=Boolean(description.trim())&&normalized.length>0&&normalized.every(line=>{const account=accounts.find(item=>item.accountId===line.accountId);return Boolean(account&&line.description.trim()&&(line.debit>0)!==(line.credit>0)&&(!account.requiresParty||line.partyId))});
  const save=useMutation({mutationFn:()=>accountingApi.saveOpeningBalance({batchId,businessId,effectiveOn,currencyCode:"COP",description:description.trim(),rowVersion,lines:normalized.map(line=>({accountId:line.accountId,partyId:line.partyId,costCenterId:line.costCenterId,description:line.description.trim(),debit:line.debit,credit:line.credit}))}),onSuccess:async value=>{client.setQueryData(queryKey,value);setBatchId(value.batchId);setRowVersion(value.rowVersion);await refresh();toast.success("Borrador de saldos iniciales guardado")},onError:showError});
  const approve=useMutation({mutationFn:()=>accountingApi.approveOpeningBalance(batchId),onSuccess:async value=>{client.setQueryData(queryKey,value);await refresh();toast.success("Saldos iniciales aprobados y listos para activar")},onError:showError});
  return <Card className="overflow-hidden rounded-3xl"><CardHeader className="border-b bg-muted/30"><div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><CardTitle>Saldos iniciales</CardTitle><Badge variant={status==="Draft"?"outline":"secondary"}>{status==="Draft"?"Borrador":status==="Approved"?"Aprobado":"Contabilizado"}</Badge></div><p className="mt-1 max-w-3xl text-sm text-muted-foreground">Registra el estado contable con el que empieza este negocio. Al activar con saldos aprobados, Auraly genera el asiento de apertura y todos los movimientos posteriores parten de él.</p></div><Field label="Fecha efectiva"><Input className="w-48" type="date" value={effectiveOn} disabled={accountingReady} onChange={event=>setEffectiveOn(event.target.value)}/></Field></div></CardHeader><CardContent className="space-y-4 p-0"><div className="grid gap-4 p-5 md:grid-cols-[1fr_auto]"><Field label="Descripción del asiento"><Input value={description} disabled={!editable} maxLength={300} onChange={event=>setDescription(event.target.value)}/></Field><div className="flex items-end gap-2"><Button type="button" variant="outline" disabled={!editable} onClick={()=>setLines(current=>[...current,emptyLine()])}><Plus className="mr-2 h-4 w-4"/>Agregar línea</Button></div></div><div className="overflow-x-auto border-y"><table className="w-full min-w-[1120px] text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Cuenta PUC</th><th className="text-left">Tercero</th><th className="text-left">Centro de costo</th><th className="text-left">Descripción</th><th className="text-right">Débito</th><th className="text-right">Crédito</th><th className="w-12"/></tr></thead><tbody>{lines.map((line,index)=>{const account=accounts.find(item=>item.accountId===line.accountId);return <tr key={index} className="border-t align-top"><td className="p-2"><Select value={line.accountId} disabled={!editable} onValueChange={accountId=>update(index,{accountId,partyId:accounts.find(item=>item.accountId===accountId)?.requiresParty?line.partyId:null})}><SelectTrigger><SelectValue placeholder="Seleccionar cuenta"/></SelectTrigger><SelectContent>{accounts.map(item=><SelectItem key={item.accountId} value={item.accountId}>{item.code} · {item.name}</SelectItem>)}</SelectContent></Select>{account?.requiresParty&&<small className="text-amber-700">Esta cuenta exige tercero.</small>}</td><td className="p-2"><PartySelect value={line.partyId??"none"} disabled={!editable} leadingOptions={[{value:"none",label:"Sin tercero"}]} placeholder="Buscar cualquier tercero" onChange={value=>update(index,{partyId:value==="none"?null:value})}/></td><td className="p-2"><Select value={line.costCenterId??"none"} disabled={!editable} onValueChange={value=>update(index,{costCenterId:value==="none"?null:value})}><SelectTrigger><SelectValue placeholder="Sin centro"/></SelectTrigger><SelectContent><SelectItem value="none">Sin centro</SelectItem>{centers.map(center=><SelectItem key={center.costCenterId} value={center.costCenterId}>{center.code} · {center.name}</SelectItem>)}</SelectContent></Select></td><td className="p-2"><Input value={line.description} disabled={!editable} maxLength={300} onChange={event=>update(index,{description:event.target.value})}/></td><td className="p-2"><Input className="text-right" type="number" min="0" step="0.01" value={line.debit} disabled={!editable} onChange={event=>update(index,{debit:event.target.value,credit:event.target.value?"":line.credit})}/></td><td className="p-2"><Input className="text-right" type="number" min="0" step="0.01" value={line.credit} disabled={!editable} onChange={event=>update(index,{credit:event.target.value,debit:event.target.value?"":line.debit})}/></td><td className="p-2"><Button type="button" size="icon" variant="ghost" disabled={!editable||lines.length<=1} aria-label="Eliminar línea" onClick={()=>setLines(current=>current.filter((_,position)=>position!==index))}><Trash2 className="h-4 w-4"/></Button></td></tr>})}</tbody><tfoot className="border-t-2 bg-muted/30 font-bold"><tr><td className="p-3" colSpan={4}>Totales {balanced&&<span className="ml-2 text-emerald-700">· Cuadrado</span>}</td><td className="text-right">{money.format(debit)}</td><td className="text-right">{money.format(credit)}</td><td/></tr></tfoot></table></div>{opening.isLoading&&<p className="p-6 text-center text-sm text-muted-foreground">Cargando saldos iniciales…</p>}<div className="flex flex-col gap-3 p-5 pt-0 sm:flex-row sm:items-center sm:justify-between"><p className="text-sm text-muted-foreground">La descripción es texto libre porque documenta el asiento. Cuenta, tercero y centro se seleccionan desde sus tablas maestras.</p><div className="flex gap-2"><Button type="button" variant="outline" disabled={!editable||!valid||save.isPending} onClick={()=>save.mutate()}>{save.isPending&&<Loader2 className="mr-2 h-4 w-4 animate-spin"/>}Guardar borrador</Button><Button type="button" disabled={!editable||!opening.data||!balanced||approve.isPending} onClick={()=>approve.mutate()}>{approve.isPending&&<Loader2 className="mr-2 h-4 w-4 animate-spin"/>}Aprobar saldos</Button></div></div></CardContent></Card>
}

function AutomationSection({categories,accounts,mapped,mappedCount,scope,setScope,pending,onMap}:{categories:Array<{category:string;displayName:string;isRequired:boolean}>;accounts:Array<{accountId:string;code:string;name:string}>;mapped:Map<string,string>;mappedCount:number;scope:"tenant"|"business";setScope:(value:"tenant"|"business")=>void;pending:boolean;onMap:(category:string,accountId:string)=>void}){const requiredCount=categories.filter(item=>item.isRequired).length;return <Card className="overflow-hidden rounded-3xl"><CardHeader className="border-b bg-muted/30"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle>Cuentas automáticas</CardTitle><p className="mt-1 text-sm text-muted-foreground">Cada concepto debe apuntar a una cuenta contabilizable. {mappedCount}/{requiredCount} completos.</p></div><Select value={scope} onValueChange={value=>setScope(value as "tenant"|"business")}><SelectTrigger className="w-56"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="tenant">Regla general de la empresa</SelectItem><SelectItem value="business">Excepción para esta sede</SelectItem></SelectContent></Select></div></CardHeader><CardContent className="p-0"><div className="grid lg:grid-cols-2">{categories.map(item=><div key={item.category} className="grid grid-cols-[minmax(0,1fr)_minmax(13rem,1.2fr)] items-center gap-3 border-b p-4 lg:odd:border-r"><div><strong className="text-sm">{item.displayName}</strong><small className="block text-muted-foreground">{item.category}</small></div><Select value={mapped.get(item.category)??""} disabled={pending||!accounts.length} onValueChange={accountId=>onMap(item.category,accountId)}><SelectTrigger className={mapped.has(item.category)?"":"border-amber-400 bg-amber-50"}><SelectValue placeholder="Seleccionar cuenta"/></SelectTrigger><SelectContent>{accounts.map(account=><SelectItem key={account.accountId} value={account.accountId}>{account.code} · {account.name}</SelectItem>)}</SelectContent></Select></div>)}</div></CardContent></Card>}

function AccountsSection({tenantId,rows,refresh}:{tenantId:string;rows:Array<{accountId:string;code:string;name:string;accountType:string;allowsPosting:boolean;requiresParty:boolean;isActive:boolean}>;refresh:()=>Promise<unknown>}){const types=useReferenceOptions("accounting-account-type"),labels=new Map((types.data??[]).map(item=>[item.code,item.label]));const [code,setCode]=useState(""),[name,setName]=useState(""),[type,setType]=useState("Asset"),[party,setParty]=useState(false);const mutation=useMutation({mutationFn:()=>accountingApi.createAccount({accountId:crypto.randomUUID(),tenantId,code,name,accountType:type,allowsPosting:true,requiresParty:party}),onSuccess:async()=>{setCode("");setName("");await refresh();toast.success("Cuenta creada")},onError:showError});return <div className="grid gap-5 xl:grid-cols-[23rem_1fr]"><Card className="h-fit rounded-3xl"><CardHeader><CardTitle>Nueva cuenta auxiliar</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={event=>submit(event,mutation.mutate)}><Field label="Código PUC"><Input value={code} onChange={event=>setCode(event.target.value)} required/></Field><Field label="Nombre"><Input value={name} onChange={event=>setName(event.target.value)} required/></Field><Field label="Naturaleza"><Select value={type} onValueChange={setType} disabled={types.isLoading}><SelectTrigger><SelectValue placeholder="Seleccionar naturaleza"/></SelectTrigger><SelectContent>{(types.data??[]).map(item=><SelectItem key={item.code} value={item.code}>{item.label}</SelectItem>)}</SelectContent></Select></Field><label className="flex items-center gap-2 text-sm"><Checkbox checked={party} onCheckedChange={checked=>setParty(checked===true)}/> Exige tercero</label><Button className="w-full" disabled={mutation.isPending||types.isLoading||!type}>Crear cuenta</Button></form></CardContent></Card><Card className="overflow-hidden rounded-3xl"><CardHeader><CardTitle>Plan Único de Cuentas operativo</CardTitle></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-muted/50 text-left"><tr><th className="p-3">Código</th><th>Cuenta</th><th>Naturaleza</th><th>Tercero</th><th>Estado</th></tr></thead><tbody>{rows.map(row=><tr key={row.accountId} className="border-t"><td className="p-3 font-mono font-semibold">{row.code}</td><td>{row.name}</td><td>{labels.get(row.accountType)??row.accountType}</td><td>{row.requiresParty?"Sí":"No"}</td><td><Badge variant={row.isActive?"secondary":"outline"}>{row.isActive?"Activa":"Inactiva"}</Badge></td></tr>)}</tbody></table></div></CardContent></Card></div>}

function CentersSection({businessId,rows,refresh}:{businessId:string;rows:Array<{costCenterId:string;code:string;name:string;isDefault:boolean;isActive:boolean}>;refresh:()=>Promise<unknown>}){const [code,setCode]=useState(""),[name,setName]=useState(""),[isDefault,setDefault]=useState(false);const mutation=useMutation({mutationFn:()=>accountingApi.createCostCenter({costCenterId:crypto.randomUUID(),businessId,code,name,parentCostCenterId:null,isDefault}),onSuccess:async()=>{setCode("");setName("");await refresh();toast.success("Centro de costo creado")},onError:showError});return <div className="grid gap-5 lg:grid-cols-[24rem_1fr]"><Card className="h-fit rounded-3xl"><CardHeader><CardTitle>Nuevo centro de costo</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={event=>submit(event,mutation.mutate)}><Field label="Código"><Input value={code} onChange={event=>setCode(event.target.value)} required/></Field><Field label="Nombre"><Input value={name} onChange={event=>setName(event.target.value)} required/></Field><label className="flex items-center gap-2 text-sm"><Checkbox checked={isDefault} onCheckedChange={checked=>setDefault(checked===true)}/> Centro predeterminado</label><Button className="w-full" disabled={mutation.isPending}>Crear centro</Button></form></CardContent></Card><SummaryCards title="Centros configurados" empty="No hay centros de costo." values={rows.map(row=>({title:`${row.code} · ${row.name}`,detail:row.isDefault?"Predeterminado":"Centro adicional",ok:row.isActive}))}/></div>}

function PeriodsSection({tenantId,rows,refresh}:{tenantId:string;rows:Array<{periodId:string;name:string;startsOn:string;endsOn:string;status:string}>;refresh:()=>Promise<unknown>}){const [name,setName]=useState(String(year)),[starts,setStarts]=useState(yearStart),[ends,setEnds]=useState(yearEnd);const create=useMutation({mutationFn:()=>accountingApi.createPeriod({periodId:crypto.randomUUID(),tenantId,startsOn:starts,endsOn:ends,name}),onSuccess:async()=>{await refresh();toast.success("Periodo creado")},onError:showError});const close=useMutation({mutationFn:accountingApi.closePeriod,onSuccess:async()=>{await refresh();toast.success("Periodo cerrado")},onError:showError});return <div className="grid gap-5 lg:grid-cols-[24rem_1fr]"><Card className="h-fit rounded-3xl"><CardHeader><CardTitle>Nuevo periodo</CardTitle></CardHeader><CardContent><form className="space-y-4" onSubmit={event=>submit(event,create.mutate)}><Field label="Nombre"><Input value={name} onChange={event=>setName(event.target.value)} required/></Field><Field label="Desde"><Input type="date" value={starts} onChange={event=>setStarts(event.target.value)} required/></Field><Field label="Hasta"><Input type="date" value={ends} onChange={event=>setEnds(event.target.value)} required/></Field><Button className="w-full" disabled={create.isPending}>Crear periodo</Button></form></CardContent></Card><Card className="rounded-3xl"><CardHeader><CardTitle>Periodos contables</CardTitle></CardHeader><CardContent className="space-y-2">{rows.map(row=><div key={row.periodId} className="flex items-center gap-3 rounded-2xl border p-4"><CalendarRange className="h-5 w-5 text-teal-700"/><div className="min-w-0 flex-1"><strong>{row.name}</strong><small className="block text-muted-foreground">{row.startsOn} a {row.endsOn}</small></div><Badge variant={row.status==="Open"?"secondary":"outline"}>{row.status==="Open"?"Abierto":"Cerrado"}</Badge>{row.status==="Open"&&<Button size="sm" variant="outline" disabled={close.isPending} onClick={()=>close.mutate(row.periodId)}>Cerrar</Button>}</div>)}{!rows.length&&<p className="text-sm text-muted-foreground">No hay periodos.</p>}</CardContent></Card></div>}

function ManualDocumentsSection({businessId,accounts,centers,payables,receivables,refresh}:{businessId:string;accounts:Array<{accountId:string;code:string;name:string;requiresParty:boolean}>;centers:Array<{costCenterId:string;code:string;name:string}>;payables:Array<{payableId:string;supplierName:string;documentNumber:string;outstandingAmount:number}>;receivables:Array<{receivableId:string;customerName:string;documentNumber:string;outstandingAmount:number}>;refresh:()=>Promise<unknown>}){
  const subledgerKinds=useReferenceOptions("accounting-subledger-kind"),directions=useReferenceOptions("accounting-adjustment-direction"),concepts=useReferenceOptions("accounting-manual-concept");
  const today=new Date().toISOString().slice(0,10),[kind,setKind]=useState<"Payable"|"Receivable">("Payable"),[subledger,setSubledger]=useState(""),[direction,setDirection]=useState<"Increase"|"Decrease">("Increase"),[amount,setAmount]=useState(""),[counterpart,setCounterpart]=useState(""),[center,setCenter]=useState("none"),[date,setDate]=useState(today),[concept,setConcept]=useState("ACCOUNT_ADJUSTMENT"),[description,setDescription]=useState("");
  const [voucherDate,setVoucherDate]=useState(today),[voucherConcept,setVoucherConcept]=useState("MANUAL_VOUCHER"),[voucherDescription,setVoucherDescription]=useState(""),[debitAccount,setDebitAccount]=useState(""),[creditAccount,setCreditAccount]=useState(""),[voucherAmount,setVoucherAmount]=useState("");
  const adjustment=useMutation({mutationFn:()=>accountingApi.confirmAdjustment({adjustmentId:crypto.randomUUID(),businessId,subledgerKind:kind,subledgerId:subledger,direction,amount:Number(amount),counterpartAccountId:counterpart,costCenterId:center==="none"?null:center,occurredAt:`${date}T12:00:00-05:00`,conceptCode:concept,description}),onSuccess:async()=>{setAmount("");setDescription("");await refresh();toast.success("Nota de cartera aceptada y enviada al motor contable")},onError:showError});
  const voucher=useMutation({mutationFn:()=>accountingApi.confirmVoucher({voucherId:crypto.randomUUID(),businessId,occurredAt:`${voucherDate}T12:00:00-05:00`,conceptCode:voucherConcept,description:voucherDescription,lines:[{accountId:debitAccount,partyId:null,costCenterId:center==="none"?null:center,description:voucherDescription,debit:Number(voucherAmount),credit:0},{accountId:creditAccount,partyId:null,costCenterId:center==="none"?null:center,description:voucherDescription,debit:0,credit:Number(voucherAmount)}]}),onSuccess:()=>{setVoucherAmount("");setVoucherDescription("");toast.success("Comprobante balanceado aceptado")},onError:showError});
  const balances=kind==="Payable"?payables.map(item=>({id:item.payableId,label:`${item.supplierName} · ${item.documentNumber} · ${money.format(item.outstandingAmount)}`})):receivables.map(item=>({id:item.receivableId,label:`${item.customerName} · ${item.documentNumber} · ${money.format(item.outstandingAmount)}`}));
  const voucherAccounts=accounts.filter(item=>!item.requiresParty);
  return <div className="grid gap-5 xl:grid-cols-2"><Card className="rounded-3xl"><CardHeader><CardTitle>Nota débito o crédito de cartera</CardTitle><p className="text-sm text-muted-foreground">Modifica CxC/CxP y genera el asiento de control en una sola operación. Una disminución nunca puede dejar saldo negativo.</p></CardHeader><CardContent><form className="grid gap-4 sm:grid-cols-2" onSubmit={event=>submit(event,adjustment.mutate)}><Field label="Auxiliar"><Select value={kind} onValueChange={value=>{setKind(value as typeof kind);setSubledger("")}}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{(subledgerKinds.data??[]).map(item=><SelectItem key={item.code} value={item.code}>{item.label}</SelectItem>)}</SelectContent></Select></Field><Field label="Efecto"><Select value={direction} onValueChange={value=>setDirection(value as typeof direction)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{(directions.data??[]).map(item=><SelectItem key={item.code} value={item.code}>{item.label}</SelectItem>)}</SelectContent></Select></Field><div className="sm:col-span-2"><Field label="Documento y tercero"><Select value={subledger} onValueChange={setSubledger}><SelectTrigger><SelectValue placeholder="Seleccionar saldo"/></SelectTrigger><SelectContent>{balances.map(item=><SelectItem key={item.id} value={item.id}>{item.label}</SelectItem>)}</SelectContent></Select></Field></div><Field label="Cuenta contrapartida"><AccountSelect value={counterpart} accounts={accounts} onChange={setCounterpart}/></Field><Field label="Valor"><Input type="number" min="0.01" step="0.01" value={amount} onChange={event=>setAmount(event.target.value)} required/></Field><Field label="Fecha"><Input type="date" value={date} onChange={event=>setDate(event.target.value)} required/></Field><Field label="Concepto"><Select value={concept} onValueChange={setConcept}><SelectTrigger><SelectValue placeholder="Seleccionar concepto"/></SelectTrigger><SelectContent>{(concepts.data??[]).map(item=><SelectItem key={item.code} value={item.code}>{item.label}</SelectItem>)}</SelectContent></Select></Field><div className="sm:col-span-2"><Field label="Descripción contable"><Input value={description} maxLength={500} onChange={event=>setDescription(event.target.value)} required/></Field></div><Button className="sm:col-span-2" disabled={adjustment.isPending||!subledger||!counterpart||!concept}>Confirmar nota</Button></form></CardContent></Card><Card className="rounded-3xl"><CardHeader><CardTitle>Comprobante manual</CardTitle><p className="text-sm text-muted-foreground">Reclasificación simple de partida doble. No modifica cartera salvo que se use la nota específica de la izquierda.</p></CardHeader><CardContent><form className="grid gap-4 sm:grid-cols-2" onSubmit={event=>submit(event,voucher.mutate)}><Field label="Cuenta débito"><AccountSelect value={debitAccount} accounts={voucherAccounts} onChange={setDebitAccount}/></Field><Field label="Cuenta crédito"><AccountSelect value={creditAccount} accounts={voucherAccounts} onChange={setCreditAccount}/></Field><Field label="Valor"><Input type="number" min="0.01" step="0.01" value={voucherAmount} onChange={event=>setVoucherAmount(event.target.value)} required/></Field><Field label="Fecha"><Input type="date" value={voucherDate} onChange={event=>setVoucherDate(event.target.value)} required/></Field><Field label="Concepto"><Select value={voucherConcept} onValueChange={setVoucherConcept}><SelectTrigger><SelectValue placeholder="Seleccionar concepto"/></SelectTrigger><SelectContent>{(concepts.data??[]).map(item=><SelectItem key={item.code} value={item.code}>{item.label}</SelectItem>)}</SelectContent></Select></Field><Field label="Centro de costo"><Select value={center} onValueChange={setCenter}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="none">Predeterminado</SelectItem>{centers.map(item=><SelectItem key={item.costCenterId} value={item.costCenterId}>{item.code} · {item.name}</SelectItem>)}</SelectContent></Select></Field><div className="sm:col-span-2"><Field label="Descripción contable"><Input value={voucherDescription} maxLength={500} onChange={event=>setVoucherDescription(event.target.value)} required/></Field></div><Button className="sm:col-span-2" disabled={voucher.isPending||!voucherConcept||!debitAccount||!creditAccount||debitAccount===creditAccount}>Confirmar comprobante</Button></form></CardContent></Card></div>
}

function AccountSelect({value,accounts,onChange}:{value:string;accounts:Array<{accountId:string;code:string;name:string}>;onChange:(value:string)=>void}){return <Select value={value} onValueChange={onChange}><SelectTrigger><SelectValue placeholder="Seleccionar cuenta"/></SelectTrigger><SelectContent>{accounts.map(item=><SelectItem key={item.accountId} value={item.accountId}>{item.code} · {item.name}</SelectItem>)}</SelectContent></Select>}

function ComplianceSection({contextKey,businessId,accounts}:{contextKey:string;businessId:string;accounts:Array<{accountId:string;code:string;name:string}>}){
  const queryClient=useQueryClient(),[taxYear,setTaxYear]=useState(2025),[selected,setSelected]=useState(""),[accountId,setAccountId]=useState(""),[concept,setConcept]=useState(""),[targetField,setTargetField]=useState("value"),[businessScope,setBusinessScope]=useState(true);
  const definitions=useQuery({queryKey:["compliance-definitions",contextKey,taxYear],queryFn:()=>accountingApi.complianceDefinitions(taxYear)});
  const current=definitions.data?.find(item=>`${item.formatCode}:${item.formatVersion}`===selected)??definitions.data?.[0];
  const mappings=useQuery({queryKey:["compliance-mappings",contextKey,taxYear,current?.formatCode],queryFn:()=>accountingApi.complianceMappings(taxYear,current?.formatCode),enabled:Boolean(current)});
  const runs=useQuery({queryKey:["compliance-runs",contextKey,taxYear],queryFn:()=>accountingApi.complianceRuns(taxYear)});
  const save=useMutation({mutationFn:()=>accountingApi.setComplianceMapping({businessId:businessScope?businessId:null,authorityCode:current!.authorityCode,taxYear:current!.taxYear,formatCode:current!.formatCode,formatVersion:current!.formatVersion,accountId,conceptCode:concept,targetField}),onSuccess:async()=>{await queryClient.invalidateQueries({queryKey:["compliance-mappings",contextKey]});setConcept("");toast.success("Mapeo fiscal guardado")},onError:showError});
  const generate=useMutation({mutationFn:()=>accountingApi.generateComplianceReport({authorityCode:current!.authorityCode,taxYear:current!.taxYear,formatCode:current!.formatCode,formatVersion:current!.formatVersion,periodFrom:`${taxYear}-01-01`,periodTo:`${taxYear}-12-31`}),onSuccess:async result=>{await queryClient.invalidateQueries({queryKey:["compliance-runs",contextKey]});toast[result.status==="Ready"?"success":"warning"](result.status==="Ready"?"Informe reproducible generado":"Informe bloqueado: revisa las validaciones")},onError:showError});
  const definitionValue=current?`${current.formatCode}:${current.formatVersion}`:"";
  return <div className="space-y-5"><Card className="rounded-3xl"><CardHeader><CardTitle>Informes fiscales e información exógena</CardTitle><p className="text-sm text-muted-foreground">Catálogo versionado por autoridad, año, formato y resolución. Cada ejecución congela mapeos, datos de tercero, totales y huella SHA-256; el CSV es una base auditable y no reemplaza el prevalidador ni la presentación ante DIAN.</p></CardHeader><CardContent className="grid gap-4 lg:grid-cols-[10rem_1fr_auto] lg:items-end"><Field label="Año gravable"><Input type="number" min={2000} max={2200} value={taxYear} onChange={event=>{setTaxYear(Number(event.target.value));setSelected("")}}/></Field><Field label="Informe"><Select value={selected||definitionValue} onValueChange={setSelected}><SelectTrigger><SelectValue placeholder="Seleccionar definición"/></SelectTrigger><SelectContent>{(definitions.data??[]).map(item=><SelectItem key={`${item.formatCode}-${item.formatVersion}`} value={`${item.formatCode}:${item.formatVersion}`}>{item.reportKind==="Exogenous"?"Exógena":"Fiscal"} · {item.formatCode} v{item.formatVersion} · {item.name}</SelectItem>)}</SelectContent></Select></Field><Button disabled={!current||generate.isPending} onClick={()=>generate.mutate()}>{generate.isPending&&<Loader2 className="mr-2 h-4 w-4 animate-spin"/>}Generar corte anual</Button>{current&&<div className="lg:col-span-3 grid gap-2 rounded-2xl border bg-muted/30 p-4 text-sm md:grid-cols-3"><span><strong>Autoridad:</strong> {current.authorityCode}</span><span><strong>Resolución:</strong> {current.resolutionNumber}</span><span><strong>Anexo:</strong> {current.technicalAnnex}</span><span className="md:col-span-3 break-all font-mono text-xs"><strong>SHA-256 fuente:</strong> {current.sourceSha256}</span></div>}</CardContent></Card>
  {current&&<div className="grid gap-5 xl:grid-cols-[25rem_1fr]"><Card className="h-fit rounded-3xl"><CardHeader><CardTitle>Mapeo de concepto</CardTitle><p className="text-sm text-muted-foreground">La clasificación tributaria requiere decisión contable explícita; no se infiere silenciosamente.</p></CardHeader><CardContent><form className="space-y-4" onSubmit={event=>submit(event,save.mutate)}><Field label="Cuenta contable"><AccountSelect value={accountId} accounts={accounts} onChange={setAccountId}/></Field><Field label="Concepto DIAN"><Input value={concept} maxLength={24} onChange={event=>setConcept(event.target.value)} placeholder="Ej. 5001" required/></Field><Field label="Campo de valor"><Input value={targetField} maxLength={64} onChange={event=>setTargetField(event.target.value)} placeholder="Ej. deductiblePayment" required/></Field><label className="flex items-center gap-2 text-sm"><Checkbox checked={businessScope} onCheckedChange={checked=>setBusinessScope(checked===true)}/> Aplicar solo a esta sede</label><Button className="w-full" disabled={!accountId||!concept||save.isPending}>Guardar mapeo</Button></form></CardContent></Card><Card className="overflow-hidden rounded-3xl"><CardHeader><CardTitle>Mapeos activos · {current.formatCode} v{current.formatVersion}</CardTitle></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Cuenta</th><th className="text-left">Concepto</th><th className="text-left">Campo</th><th className="pr-3 text-left">Alcance</th></tr></thead><tbody>{(mappings.data??[]).map(item=><tr key={item.mappingId} className="border-t"><td className="p-3">{item.accountCode} · {item.accountName}</td><td className="font-mono">{item.conceptCode}</td><td className="font-mono">{item.targetField}</td><td className="pr-3">{item.businessId?"Sede":"Empresa"}</td></tr>)}</tbody></table>{!mappings.data?.length&&<p className="p-8 text-center text-sm text-muted-foreground">Sin mapeos. La ejecución quedará bloqueada hasta configurar al menos uno.</p>}</div></CardContent></Card></div>}
  <Card className="overflow-hidden rounded-3xl"><CardHeader><CardTitle>Ejecuciones reproducibles</CardTitle></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Creado</th><th className="text-left">Informe</th><th className="text-left">Estado</th><th className="text-right">Filas</th><th className="text-right">Control</th><th className="pr-3 text-left">Salida</th></tr></thead><tbody>{(runs.data??[]).map(run=><tr key={run.runId} className="border-t align-top"><td className="p-3 whitespace-nowrap">{new Date(run.createdAt).toLocaleString("es-CO")}</td><td>{run.formatCode} v{run.formatVersion}<small className="block text-muted-foreground">{run.name}</small></td><td><Badge variant={run.status==="Ready"?"secondary":"destructive"}>{run.status==="Ready"?"Listo":"Bloqueado"}</Badge>{run.validations.map(value=><small key={`${value.code}-${value.partyId}`} className="mt-1 block max-w-md text-destructive">{value.code}: {value.message}</small>)}</td><td className="text-right">{run.rowCount}</td><td className="text-right">{money.format(run.controlTotal)}</td><td className="pr-3">{run.status==="Ready"?<a className="font-semibold text-teal-700 underline" href={accountingApi.complianceArtifactUrl(run.runId)}>Descargar CSV auditable</a>:"Corrige y vuelve a generar"}</td></tr>)}</tbody></table>{!runs.data?.length&&<p className="p-8 text-center text-sm text-muted-foreground">Todavía no hay ejecuciones para este año.</p>}</div></CardContent></Card></div>
}

function ReportsSection({contextKey,from,to,setFrom,setTo}:{contextKey:string;from:string;to:string;setFrom:(value:string)=>void;setTo:(value:string)=>void}){
  const reportTypes=useReferenceOptions("accounting-report-type");
  const [report,setReport]=useState<"ledger"|"journal"|"balance"|"income"|"exceptions">("ledger");
  const ledger=useQuery({queryKey:["accounting-report",contextKey,"ledger",from,to],queryFn:()=>accountingApi.generalLedger(from,to),enabled:report==="ledger"});
  const journal=useQuery({queryKey:["accounting-report",contextKey,"journal",from,to],queryFn:()=>accountingApi.journal(from,to),enabled:report==="journal"});
  const balance=useQuery({queryKey:["accounting-report",contextKey,"balance",to],queryFn:()=>accountingApi.balanceSheet(to),enabled:report==="balance"});
  const income=useQuery({queryKey:["accounting-report",contextKey,"income",from,to],queryFn:()=>accountingApi.incomeStatement(from,to),enabled:report==="income"});
  const exceptions=useQuery({queryKey:["accounting-report",contextKey,"exceptions",from,to],queryFn:()=>accountingApi.exceptions(from,to),enabled:report==="exceptions"});
  return <Card className="overflow-hidden rounded-3xl"><CardHeader className="border-b"><div className="grid gap-3 lg:grid-cols-[1fr_15rem_11rem_11rem]"><div><CardTitle>Libros y estados básicos</CardTitle><p className="mt-1 text-sm text-muted-foreground">Información producida exclusivamente desde asientos contabilizados; las excepciones muestran lo pendiente.</p></div><Field label="Informe"><Select value={report} onValueChange={value=>setReport(value as typeof report)} disabled={reportTypes.isLoading}><SelectTrigger><SelectValue placeholder="Seleccionar informe"/></SelectTrigger><SelectContent>{(reportTypes.data??[]).map(item=><SelectItem key={item.code} value={item.code}>{item.label}</SelectItem>)}</SelectContent></Select></Field><Field label="Desde"><Input type="date" value={from} disabled={report==="balance"} onChange={event=>setFrom(event.target.value)}/></Field><Field label="Hasta"><Input type="date" value={to} onChange={event=>setTo(event.target.value)}/></Field></div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto">
    {report==="ledger"&&<table className="w-full text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Cuenta</th><th className="text-left">Nombre</th><th className="text-right">Inicial</th><th className="text-right">Débito</th><th className="text-right">Crédito</th><th className="pr-3 text-right">Final</th></tr></thead><tbody>{(ledger.data??[]).map(row=><tr key={row.accountCode} className="border-t"><td className="p-3 font-mono">{row.accountCode}</td><td>{row.accountName}</td><td className="text-right">{money.format(row.openingBalance)}</td><td className="text-right">{money.format(row.debit)}</td><td className="text-right">{money.format(row.credit)}</td><td className="pr-3 text-right font-semibold">{money.format(row.closingBalance)}</td></tr>)}</tbody></table>}
    {report==="journal"&&<table className="w-full min-w-[900px] text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Fecha / asiento</th><th className="text-left">Documento</th><th className="text-left">Cuenta</th><th className="text-left">Descripción</th><th className="text-right">Débito</th><th className="pr-3 text-right">Crédito</th></tr></thead><tbody>{(journal.data??[]).map(row=><tr key={`${row.entryId}-${row.lineNumber}`} className="border-t"><td className="p-3">{new Date(row.occurredAt).toLocaleDateString("es-CO")}<small className="block font-mono">{row.entryNumber}</small></td><td>{row.sourceDocumentType}<small className="block text-muted-foreground">{row.sourceDocumentId.slice(0,8)}</small></td><td>{row.accountCode} · {row.accountName}</td><td>{row.description}</td><td className="text-right">{money.format(row.debit)}</td><td className="pr-3 text-right">{money.format(row.credit)}</td></tr>)}</tbody></table>}
    {(report==="balance"||report==="income")&&<StatementTable rows={report==="balance"?(balance.data??[]):(income.data??[])}/>}
    {report==="exceptions"&&<table className="w-full text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Fecha</th><th className="text-left">Documento</th><th className="text-left">Estado</th><th className="text-left">Código</th><th className="pr-3 text-left">Detalle</th></tr></thead><tbody>{(exceptions.data??[]).map(row=><tr key={row.sourceDocumentId} className="border-t"><td className="p-3">{new Date(row.occurredAt).toLocaleDateString("es-CO")}</td><td>{row.sourceDocumentType} · {row.sourceDocumentId.slice(0,8)}</td><td>{row.status}</td><td>{row.errorCode??"—"}</td><td className="pr-3">{row.errorMessage??"Pendiente de procesamiento"}</td></tr>)}</tbody></table>}
  </div></CardContent></Card>
}

function StatementTable({rows}:{rows:Array<{section:string;accountCode:string;accountName:string;amount:number}>}){const types=useReferenceOptions("accounting-account-type"),labels=new Map((types.data??[]).map(item=>[item.code,item.label])),totals=rows.reduce((result,row)=>result.set(row.section,(result.get(row.section)??0)+row.amount),new Map<string,number>());return <table className="w-full text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Sección</th><th className="text-left">Cuenta</th><th className="text-left">Nombre</th><th className="pr-3 text-right">Valor</th></tr></thead><tbody>{rows.map(row=><tr key={`${row.section}-${row.accountCode}`} className="border-t"><td className="p-3">{labels.get(row.section)??row.section}</td><td className="font-mono">{row.accountCode}</td><td>{row.accountName}</td><td className="pr-3 text-right font-semibold">{money.format(row.amount)}</td></tr>)}{[...totals].map(([section,total])=><tr key={`total-${section}`} className="border-t bg-muted/30 font-bold"><td className="p-3" colSpan={3}>Total {labels.get(section)??section}</td><td className="pr-3 text-right">{money.format(total)}</td></tr>)}</tbody></table>}

function BalanceSection({contextKey,from,to,setFrom,setTo,rows,loading,refresh}:{contextKey:string;from:string;to:string;setFrom:(v:string)=>void;setTo:(v:string)=>void;rows:Array<{accountCode:string;accountName:string;debit:number;credit:number;balance:number}>;loading:boolean;refresh:()=>void}){
  const [selected,setSelected]=useState<(typeof rows)[number]|null>(null);
  const movements=useQuery({queryKey:["account-movements",contextKey,selected?.accountCode,from,to],queryFn:()=>accountingApi.accountMovements(selected!.accountCode,from,to),enabled:Boolean(selected)});
  const totals=rows.reduce((value,row)=>({debit:value.debit+row.debit,credit:value.credit+row.credit}),{debit:0,credit:0});
  return <>
    <Card className="overflow-hidden rounded-3xl"><CardHeader className="border-b"><div className="flex flex-col gap-3 lg:flex-row lg:items-end"><div className="flex-1"><CardTitle>Balance de comprobación</CardTitle><p className="mt-1 text-sm text-muted-foreground">Saldos reales de los documentos contabilizados en el periodo. Selecciona una cuenta para ver sus movimientos.</p></div><Field label="Desde"><Input type="date" value={from} onChange={event=>setFrom(event.target.value)}/></Field><Field label="Hasta"><Input type="date" value={to} onChange={event=>setTo(event.target.value)}/></Field><Button variant="outline" onClick={refresh} disabled={loading}><RefreshCw className={`mr-2 h-4 w-4 ${loading?"animate-spin":""}`}/>Actualizar</Button></div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-muted/50"><tr><th className="p-3 text-left">Cuenta</th><th className="text-left">Nombre</th><th className="text-right">Débito</th><th className="text-right">Crédito</th><th className="pr-4 text-right">Saldo</th><th className="w-10"/></tr></thead><tbody>{rows.map(row=><tr key={row.accountCode} tabIndex={0} role="button" onClick={()=>setSelected(row)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();setSelected(row)}}} className="cursor-pointer border-t outline-none transition-colors hover:bg-muted/50 focus-visible:bg-muted/50"><td className="p-3 font-mono font-semibold">{row.accountCode}</td><td>{row.accountName}</td><td className="text-right">{money.format(row.debit)}</td><td className="text-right">{money.format(row.credit)}</td><td className="pr-4 text-right font-semibold">{money.format(row.balance)}</td><td><ChevronRight className="h-4 w-4 text-muted-foreground"/></td></tr>)}</tbody><tfoot className="border-t-2 bg-muted/30 font-bold"><tr><td className="p-3" colSpan={2}>Totales</td><td className="text-right">{money.format(totals.debit)}</td><td className="text-right">{money.format(totals.credit)}</td><td className="pr-4 text-right">{money.format(totals.debit-totals.credit)}</td><td/></tr></tfoot></table>{!loading&&!rows.length&&<p className="p-10 text-center text-muted-foreground">No hay movimientos contabilizados en este rango.</p>}</div></CardContent></Card>
    <Dialog open={Boolean(selected)} onOpenChange={open=>{if(!open)setSelected(null)}}><DialogContent className="max-w-6xl"><DialogHeader><DialogTitle>{selected?.accountCode} · {selected?.accountName}</DialogTitle><DialogDescription>Movimientos contabilizados del {from} al {to}.</DialogDescription></DialogHeader><div className="max-h-[65vh] overflow-auto rounded-xl border"><table className="w-full min-w-[850px] text-sm"><thead className="sticky top-0 bg-muted"><tr><th className="p-3 text-left">Fecha</th><th className="text-left">Asiento</th><th className="text-left">Documento</th><th className="text-left">Descripción</th><th className="text-right">Débito</th><th className="text-right">Crédito</th><th className="pr-3 text-right">Saldo</th></tr></thead><tbody>{(movements.data??[]).map(item=><tr key={`${item.entryId}-${item.description}`} className="border-t"><td className="whitespace-nowrap p-3">{new Date(item.occurredAt).toLocaleDateString("es-CO")}</td><td className="font-mono">{item.entryNumber}</td><td><span className="block">{item.sourceDocumentType}</span><small className="text-muted-foreground">{item.sourceDocumentId.slice(0,8)}</small></td><td>{item.description}</td><td className="text-right">{money.format(item.debit)}</td><td className="text-right">{money.format(item.credit)}</td><td className="pr-3 text-right font-semibold">{money.format(item.balance)}</td></tr>)}</tbody></table>{movements.isLoading&&<p className="p-10 text-center text-muted-foreground">Cargando movimientos…</p>}{!movements.isLoading&&!movements.data?.length&&<p className="p-10 text-center text-muted-foreground">No hay movimientos para esta cuenta en el rango.</p>}</div></DialogContent></Dialog>
  </>
}

function StatusCard({label,value,ok}:{label:string;value:string;ok:boolean}){return <Card className="rounded-2xl"><CardContent className="flex items-center gap-3 p-4">{ok?<CheckCircle2 className="h-8 w-8 text-emerald-600"/>:<AlertTriangle className="h-8 w-8 text-amber-600"/>}<div><small className="text-muted-foreground">{label}</small><strong className="block text-sm">{value}</strong></div></CardContent></Card>}
function Nav({active,icon:Icon,onClick,children}:{active:boolean;icon:typeof Landmark;onClick:()=>void;children:ReactNode}){return <button type="button" onClick={onClick} className={`flex shrink-0 items-center rounded-xl px-4 py-2.5 text-sm font-semibold ${active?"bg-slate-950 text-white shadow":"text-muted-foreground hover:bg-muted"}`}><Icon className="mr-2 h-4 w-4"/>{children}</button>}
function SummaryCards({title,values,empty}:{title:string;values:Array<{title:string;detail:string;ok:boolean}>;empty:string}){return <Card className="rounded-3xl"><CardHeader><CardTitle>{title}</CardTitle></CardHeader><CardContent className="grid gap-3 sm:grid-cols-2">{values.map(value=><div key={value.title} className="rounded-2xl border p-4"><strong className="text-sm">{value.title}</strong><small className="mt-1 block text-muted-foreground">{value.detail}</small></div>)}{!values.length&&<p className="text-sm text-muted-foreground">{empty}</p>}</CardContent></Card>}
function EmptyContext(){return <div className="rounded-3xl border border-dashed p-12 text-center"><Landmark className="mx-auto h-12 w-12 text-teal-700"/><h1 className="mt-4 text-xl font-bold">Selecciona una empresa y una sede</h1><p className="mt-2 text-sm text-muted-foreground">La configuración contable se aplica dentro de ese contexto.</p></div>}
function submit(event:FormEvent,mutate:()=>void){event.preventDefault();mutate()}
function showError(error:unknown){toast.error(error instanceof Error?error.message:"No fue posible completar la operación")}
function Field({label,children}:{label:string;children:ReactNode}){return <div className="space-y-2"><Label>{label}</Label>{children}</div>}
